11	  // Pattern: type/([base]+)?suffix where suffix is json
12	  JSON: /^[\w\-.+]+\/([\w\-.+]+\+)?json$/,
13	  // Matches: application/xml, text/xml, application/atom+xml, application/rss+xml, application/xhtml+xml, etc.
