184	  if (!bodySchema) return '';
185	
186	  // String example = raw XML, return as-is
187	  if (typeof bodySchema.example === 'string') {
188	    return bodySchema.example;
189	  }
190	
191	  const exampleValues = typeof bodySchema.example === 'object' ? bodySchema.example : null;
192	
193	  if (!bodySchema.properties && !exampleValues) return '';
194	
195	  const rootName = bodySchema.xml?.name || 'root';
196	
197	  // Build a single XML element
198	  const buildElement = (name, prop = {}, value, indent = '  ') => {
199	    const xmlName = prop.xml?.name || name;
200	
201	    if (prop.xml?.attribute) return null;
202	
203	    // Nested object - recurse into children
204	    if (typeof value === 'object' && value !== null && !Array.isArray(value)) {
205	      const children = Object.entries(value)
206	        .map(([k, v]) => buildElement(k, prop.properties?.[k] || {}, v, indent + '  '))
207	        .filter(Boolean);
208	      return `${indent}<${xmlName}>${children.length ? '\n' + children.join('\n') + '\n' + indent : ''}</${xmlName}>`;
209	    }
210	
211	    // Object schema without value - build empty structure from schema
212	    if (prop.type === 'object' || prop.properties) {
213	      const children = Object.entries(prop.properties || {})
214	        .map(([k, p]) => buildElement(k, p, undefined, indent + '  '))
